import java.io.*;
import java.util.*;

public class Main {
    static long n;
    static long sx, sy, dx, dy, t;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        sx = sc.nextLong();
        sy = sc.nextLong();
        dx = sc.nextLong();
        dy = sc.nextLong();
        t = sc.nextLong();

        long x = sx, y = sy;
        long cdx = dx, cdy = dy;
        long time = 0;

        while (time < t) {
            long k = (x + y) + (time); // x+y + time (since each second adds 1 to all cells)
            long ndx = cdx + k;
            long ndy = cdy + k;

            long nx = ((x + ndx - 1) % n + n) % n + 1;
            long ny = ((y + ndy - 1) % n + n) % n + 1;

            x = nx;
            y = ny;
            cdx = ndx;
            cdy = ndy;
            time++;
        }

        System.out.println(x + " " + y);
    }
}
